package com.wanyuecity.energy.notification.provider;
import com.fasterxml.jackson.databind.*;import okhttp3.*;import org.springframework.stereotype.Component;import java.time.Duration;import java.util.Map;
@Component public class FeishuWebhookProvider implements NotificationProvider {private final OkHttpClient http=new OkHttpClient.Builder().connectTimeout(Duration.ofSeconds(5)).readTimeout(Duration.ofSeconds(10)).writeTimeout(Duration.ofSeconds(10)).build();private final ObjectMapper json;public FeishuWebhookProvider(ObjectMapper json){this.json=json;}public String provider(){return "FEISHU";}public SendResult send(String url,NotificationMessage msg){try{String body=json.writeValueAsString(Map.of("msg_type","text","content",Map.of("text",msg.content())));Request req=new Request.Builder().url(url).post(RequestBody.create(body,MediaType.get("application/json; charset=utf-8"))).build();try(Response r=http.newCall(req).execute()){String text=r.body()==null?"":r.body().string();JsonNode n=json.readTree(text);boolean ok=r.isSuccessful()&&(n.path("code").asInt(-1)==0||n.path("StatusCode").asInt(-1)==0);return new SendResult(ok,r.code(),limit(text,2000),ok?null:"provider rejected request");}}catch(Exception e){return new SendResult(false,null,null,e.getClass().getSimpleName()+": "+limit(e.getMessage(),300));}}private String limit(String s,int n){if(s==null)return null;return s.length()<=n?s:s.substring(0,n);}}

